pragma solidity >=0.8.0;
contract EventOverloadSignature {
    event Ping(uint256 a);
    event Ping(uint256 a, string b);
    uint256 public last;

    function mix() public {
        emit Ping(1);
        emit Ping(2, "x");
        emit Ping(3);
        last = 7;
    }

    function getLast() public view returns (uint256) {
        return last;
    }
}
